import numpy as np
from statsmodels.stats.correlation_tools import cov_nearest

def stats_of(a):
    a = np.asarray(a)
    return {
        'has_nan': bool(np.isnan(a).any()),
        'diag': a.diagonal().copy(),
    }

mats = {
    'zero': np.array([[2.0, 0.0],[0.0, 0.0]]),
    'neg': np.array([[2.0, 0.0],[0.0, -1e-8]]),
}
for method in ['clipped','nearest']:
    for name, mat in mats.items():
        res = cov_nearest(mat, method=method)
        s = stats_of(res)
        probe(f'{method}_{name}_has_nan', s['has_nan'])
        probe(f'{method}_{name}_diag', s['diag'])

